{
  "executive_summary": "E2E Driver uses concrete models and everyday examples (cake, shapes) strongly; the lesson's strongest area is Student Engagement where pupils use vocabulary and give explanations. The teacher reflected that pacing worked well and intends to give quieter students more wait time — this supports sustaining student participation. The key growth area remains feedback: teacher gives many prompts but few specific corrective or next-step feedback moves; building brief follow-ups and explicit wait-time will deepen learning.",
  "talk_time": {},
  "questions": {},
  "goal1_formative_assessment": {
    "summary": "Formative assessment practices are present (short checks and an end 'test' prompt) but specific feedback and SMART objectives are missing.",
    "evidence": [
      {
        "source": "Transcript",
        "timestamps": "12:59–13:20, 14:34",
        "detail": "'چلیں، میں آپ سے ٹیسٹ پوچھوں؟' (short formative check) and 'آپ نے اس کا فیکشن لکھنا ہے، پروپر فیکشن لکھنا ہے.' (written task at close)."
      },
      {
        "source": "High-leverage practices (C3)",
        "timestamps": "06:31, 11:27",
        "detail": "Feedback mainly praise/term naming rather than targeted next steps."
      }
    ],
    "notes": "No explicit DO-able 'by the end you will be able to...' objective was stated at lesson start (B1 score 0)."
  },
  "goal2_student_engagement": {
    "original_domain": "student_engagement",
    "domain_score": 9,
    "domain_max": 10,
    "indicators": [
      {
        "id": "D1",
        "name": "Diversity of Conceptual Expression",
        "score": 2,
        "evidence": "Students use multiple phrasings to describe parts and fractions (examples at 00:34 and 08:44)."
      },
      {
        "id": "D2",
        "name": "Student Reasoning in Responses",
        "score": 2,
        "evidence": "At least one student offers a short reason for a subtraction example (02:11–02:14)."
      },
      {
        "id": "D3",
        "name": "Student-Initiated Questions",
        "score": 1,
        "evidence": "Questions are mostly procedural ('میم، ٹیسٹ لکھیں؟' at 13:01)."
      },
      {
        "id": "D4",
        "name": "Spontaneous Transfer & Connection-Making",
        "score": 2,
        "evidence": "Student links cake example to own life ('my little brother's birthday' at 03:28)."
      },
      {
        "id": "D5",
        "name": "Visible Learning Progression Across the Lesson",
        "score": 2,
        "evidence": "Student talk moves from identification to use of vocabulary and fuller phrasing (00:34 → 08:44 → 13:20)."
      }
    ]
  },
  "goal3_quality_content": {
    "original_domain": "teacher_subject_knowledge",
    "domain_score": 7,
    "domain_max": 10,
    "indicators": [
      {
        "id": "F1",
        "name": "Content Accuracy",
        "score": 2,
        "evidence": "Correct definition of proper fraction given at 08:01."
      },
      {
        "id": "F2",
        "name": "Use of Academic Language",
        "score": 2,
        "evidence": "Teacher introduces and practices terms 'numerator' and 'denominator' (06:31–06:41)."
      },
      {
        "id": "F3",
        "name": "Anticipation of Student Misconceptions",
        "score": 1,
        "evidence": "Teacher corrects examples but does not explicitly name common misconceptions (12:36)."
      },
      {
        "id": "F4",
        "name": "Mathematical Discourse & Reasoning",
        "score": 1,
        "evidence": "Brief reasoning elicited but not pursued (12:12–12:27)."
      },
      {
        "id": "F5",
        "name": "Problem-Solving & Productive Struggle",
        "score": 1,
        "evidence": "Short conceptual prompts given but limited wait time or extended struggle (12:12)."
      }
    ]
  },
  "goal4_classroom_interaction": {
    "original_domain": "high_leverage_practices",
    "domain_score": 3,
    "domain_max": 8,
    "indicators": [
      {
        "id": "C1",
        "name": "Quality Questioning (Bloom's Aligned)",
        "score": 1,
        "evidence": "Open prompts used (00:22, 00:42, 01:34) but limited follow-up probing of individual student answers."
      },
      {
        "id": "C2",
        "name": "Responsive Re-explanation & Adaptive Teaching",
        "score": 2,
        "evidence": "Teacher uses multiple representations (model → cake analogy) to explain the concept (00:22, 03:00)."
      },
      {
        "id": "C3",
        "name": "Effective Feedback",
        "score": 0,
        "evidence": "Feedback is primarily praise or term-naming rather than specific guidance (06:31, 11:27)."
      },
      {
        "id": "C4",
        "name": "Student Agency & Voice",
        "score": 0,
        "evidence": "Students respond to prompts but do not choose methods or present unprompted explanations (08:44)."
      }
    ]
  },
  "goal5_classroom_management": {
    "summary": "Classroom routines and material use visible; teacher manages transitions verbally and ends with a clear task. Some room for clearer differentiation and visible routines.",
    "evidence": [
      {
        "source": "Lesson sequencing",
        "timestamps": "05:17, 12:12",
        "detail": "Teacher signals phase transitions and gives a closing written task."
      },
      {
        "source": "Photo analysis",
        "detail": "Classroom appears organised with visual aids; recommendation noted to add visible routine charts for transitions."
      }
    ]
  },
  "strengths": [
    {
      "title": "Concrete representations and real-world linkage",
      "evidence": "Teacher uses physical models and a cake analogy to make fractions concrete: 'مثلاً آپ اس کو سمجھیں یہ کیک ہے... ہم پارٹ کرتے ہیں' (03:00–03:12).",
      "analysis": "This choice of representations supported students moving from simple identification to using key vocabulary. The teacher herself reflected that pacing felt effective, which likely helped students follow the representational progression.",
      "impact": "Made the abstract idea of parts-of-a-whole accessible; students offered personal examples and could count and name parts. Teacher plans to give quieter students more wait time, which should further increase the depth of responses to these concrete prompts."
    }
  ],
  "growth_opportunities": [
    {
      "area": "Effective Feedback (C3)",
      "observation": "Feedback is mainly praise or term naming rather than targeted 'do next' guidance (examples at 06:31, 11:27).",
      "rationale": "The teacher frequently elicits student answers but rarely asks students to justify or extend their answers; the teacher recognised pacing worked well and intends to give quieter students more time — this is a helpful start that can be paired with specific follow-ups to turn answers into learning moments.",
      "strategies": [
        "After a student answers, use a short two-part feedback move: name what is correct and give one concrete next step (e.g. 'Good — you named numerator. Now show one reason why that is the numerator.').",
        "Combine extra wait-time (planned by the teacher) with targeted prompts: after waiting, ask the same student to expand, or ask a peer to paraphrase the reasoning.",
        "Use 'tell me one thing to fix' when errors appear: point out the specific mis-step and ask the student to correct it aloud."
      ]
    },
    {
      "area": "Differentiation (B6)",
      "observation": "All students received the same task; no easier/extension tasks were assigned (14:34).",
      "rationale": "Teacher already notices pacing and quieter students; differentiating tasks by difficulty or outcome will allow the teacher to use that wait time productively (e.g., prompt quieter students with scaffolded cues while faster students attempt an extension).",
      "strategies": [
        "Prepare an A/B task on the board: 'A' for scaffolded counting prompts and 'B' for extension (create two fractions or compare them). Ask faster students to do B.",
        "Assign seats or quick pairs for targeted support: ask quieter students to discuss with a neighbour for 30 seconds before reporting, using the extra wait-time the teacher plans to provide."
      ]
    }
  ],
  "scores": {
    "max_marks": 103,
    "overall_marks": 19,
    "has_lesson_plan": false,
    "overall_max_marks": 28,
    "overall_percentage": 67.9,
    "indicators_applicable": 21,
    "indicators_not_applicable": 5
  },
  "recommendations": [
    "Add one explicit learning objective at lesson start phrased as 'By the end you will be able to…' (e.g. 'identify and write proper fractions').",
    "After each student answer, give one specific feedback move: name what was correct and give one concrete next step (correction or extension).",
    "Differentiate one task: prepare an easier counting prompt and one extension prompt for fast finishers, and assign them explicitly.",
    "Use planned wait-time for quieter students (teacher's intended change): pause 3–5 seconds after asking a question, then prompt the same student to expand ('Tell me one reason why that is the numerator'), or ask a peer to paraphrase.",
    "Pair the teacher's pacing strength with feedback practice: when you note a response and then wait, follow with 'Why?' or 'How do you know?' to elicit reasoning rather than only terminology."
  ],
  "notable_moments": [
    {
      "what_happened": "The teacher repeatedly asked for the definition of a fraction. Students offered words like 'shape' and examples like 'windows.' The collective response was fragmented, with no one providing a clear definition.",
      "approx_time_phrase": "in the first few minutes",
      "significance_reason_en": "This shows the class as a whole does not have a ready, shared understanding of the term 'fraction,' forcing the teacher to build it from scratch using examples."
    },
    {
      "what_happened": "Whenever the teacher presented a new partitioned shape (circle, rectangle, square) and asked how many parts, students chorused the total count correctly ('4', '8', '5').",
      "approx_time_phrase": "during the modeling with shapes",
      "significance_reason_en": "The class is consistently and successfully engaged in the concrete step of counting total parts, which is the foundation for the denominator."
    },
    {
      "what_happened": "After the teacher introduced the words 'numerator' and 'denominator,' students repeated them correctly in chorus multiple times.",
      "approx_time_phrase": "when learning the terms",
      "significance_reason_en": "The class successfully acquired and practiced the new vocabulary, showing they can learn and repeat the key terms, even if application is still shaky."
    },
    {
      "scope": "individual",
      "what_happened": "A student connected the cake example to their life: 'My little brother's birthday' when the teacher asked about sharing cake.",
      "approx_time_phrase": "around 03:28",
      "significance_reason_en": "A good transfer to personal context that shows the real-world analogy resonated with at least some students."
    },
    {
      "scope": "individual",
      "what_happened": "A student correctly identified '3/7' as a proper fraction but could not fully articulate the rule (numerator < denominator), repeating '3,7,3.'",
      "approx_time_phrase": "near the end of the lesson",
      "significance_reason_en": "Shows pattern recognition but limited conceptual articulation; a chance for targeted feedback and prompting for reasoning."
    }
  ],
  "domain4_professional_responsibilities": {
    "reflection_quality": "Teacher offers a concise reflection: notes pacing worked well and identifies a specific change (give quieter students more time).",
    "self_awareness": "Teacher recognises that some students are quieter and that pacing affects participation; this indicates awareness of an in-class variable affecting learning.",
    "growth_orientation": "Teacher expresses an intention to change classroom practice (use more wait time), showing a practical growth mindset.",
    "professional_learning_needs": "Teacher might benefit from short coaching on targeted feedback moves and questioning strategies that combine wait-time with follow-up prompts to elicit justification.",
    "score": 3,
    "justification": "The teacher demonstrates clear self-awareness and a concrete next step (give quieter students more time). Reflection is constructive but brief and would be stronger with concrete examples or planned measures for monitoring impact. Score 3 recognises good reflective practice and growth orientation with some room for deeper analysis."
  },
  "debrief_reflection": {
    "reflection_quality": {
      "competency_score": 2,
      "evidence": "Teacher: \"I think the pacing worked well, and next time I would give the quieter students more time to answer.\"",
      "justification": "Teacher identifies a strength (pacing) and a targeted change (allow more time). This is a critical identification of gap and a justified action, though brief."
    },
    "connecting_to_incidents": {
      "competency_score": 1,
